    def extract_igdb_store_links(game: dict) -> list[dict]:
        """
        Extract store links from IGDB external_games and websites.

        These are distribution/store links:
        Steam, Epic, GOG, Microsoft/Xbox, PlayStation, Nintendo.
        """

